package com.example.ancapp

import android.app.Application
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.time.LocalDate

sealed interface Screen {
  data object Register : Screen
  data class Detail(val patient: Patient) : Screen
  data class NewVisit(val patient: Patient) : Screen
}

class AncViewModel(app: Application) : AndroidViewModel(app) {
  private val db = AncDatabase(app)

  var screen by mutableStateOf<Screen>(Screen.Register)
    private set
  var patients by mutableStateOf<List<Patient>>(emptyList())
    private set
  var visits by mutableStateOf<List<Visit>>(emptyList())
    private set

  init {
    viewModelScope.launch {
      patients = withContext(Dispatchers.IO) { db.pregnantPatients(LocalDate.now()) }
    }
  }

  fun openPatient(patient: Patient) {
    screen = Screen.Detail(patient)
    visits = emptyList()
    viewModelScope.launch {
      visits = withContext(Dispatchers.IO) { db.visits(patient.id) }
    }
  }

  fun newVisit(patient: Patient) {
    screen = Screen.NewVisit(patient)
  }

  fun back() {
    when (val s = screen) {
      is Screen.NewVisit -> openPatient(s.patient)
      else -> screen = Screen.Register
    }
  }

  fun saveVisit(visit: Visit) {
    viewModelScope.launch {
      withContext(Dispatchers.IO) { db.addVisit(visit) }
      back()
    }
  }
}

