class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent {
      MaterialTheme {
        Surface(Modifier.fillMaxSize()) {
          val vm: AncViewModel = viewModel()
          BackHandler(enabled = vm.screen != Screen.Register) { vm.back() }
          when (val screen = vm.screen) {
            Screen.Register -> RegisterScreen(vm.patients, onOpen = vm::openPatient)
            is Screen.Detail -> DetailScreen(
              patient = screen.patient,
              visits = vm.visits,
              onBack = vm::back,
              onNewVisit = { vm.newVisit(screen.patient) },
            )
            is Screen.NewVisit -> VisitFormScreen(screen.patient, onSave = vm::saveVisit, onCancel = vm::back)
          }
        }
      }
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(patients: List<Patient>, onOpen: (Patient) -> Unit) {
  val today = LocalDate.now()
  Scaffold(topBar = { TopAppBar(title = { Text("Pregnant patients") }) }) { padding ->
    if (patients.isEmpty()) {
      Text("No pregnant patients on file.", Modifier.padding(padding).padding(16.dp))
    } else {
      LazyColumn(Modifier.padding(padding)) {
        items(patients, key = { it.id }) { p ->
          ListItem(
            headlineContent = { Text(p.name) },
            supportingContent = {
              Text("Age ${p.ageOn(today)} · Due ${p.dueDate} · ${p.gestationalWeeksOn(today)} weeks")
            },
            modifier = Modifier.clickable { onOpen(p) },
          )
          HorizontalDivider()
        }
      }
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DetailScreen(patient: Patient, visits: List<Visit>, onBack: () -> Unit, onNewVisit: () -> Unit) {
  val today = LocalDate.now()
  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text(patient.name) },
        navigationIcon = {
          IconButton(onClick = onBack) { Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back") }
        },
      )
    },
    floatingActionButton = {
      ExtendedFloatingActionButton(
        onClick = onNewVisit,
        icon = { Icon(Icons.Default.Add, null) },
        text = { Text("New visit") },
      )
    },
  ) { padding ->
    LazyColumn(
      Modifier.padding(padding),
      contentPadding = PaddingValues(16.dp),
      verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
      item {
        Text("Age ${patient.ageOn(today)} · Due ${patient.dueDate} · ${patient.gestationalWeeksOn(today)} weeks")
        Text(
          "Past ANC visits",
          style = MaterialTheme.typography.titleMedium,
          modifier = Modifier.padding(top = 16.dp),
        )
      }
      if (visits.isEmpty()) item { Text("No visits recorded.") }
      items(visits, key = { it.id }) { v -> VisitCard(v) }
    }
  }
}

@Composable
fun VisitCard(v: Visit) {
  Card(Modifier.fillMaxWidth()) {
    Column(Modifier.padding(12.dp)) {
      Text("${v.date} · ${v.gestationWeeks} weeks", style = MaterialTheme.typography.titleSmall)
      Text(
        "Weight ${v.weightKg} kg · BP ${v.systolic}/${v.diastolic} mmHg" +
          (v.hemoglobin?.let { " · Hb $it g/dL" } ?: ""),
      )
      if (v.dangerSigns.isNotEmpty()) {
        Text(
          "Danger signs: ${v.dangerSigns.joinToString { it.label }}",
          color = MaterialTheme.colorScheme.error,
        )
      }
      if (v.notes.isNotBlank()) Text(v.notes)
    }
  }
